module buffet_optimizer (input clk, input rst_n, input start, input [7:0] dish_count, input [7:0] total_weight, input [7:0] dish_info_index, input [47:0] dish_data, input dish_data_valid, output reg [31:0] result, output reg done, output reg error); always @(posedge clk) begin if (!rst_n) begin result <= 32'h00000000; done <= 1'b0; error <= 1'b0; end else begin if (start) begin done <= 1'b1; error <= 1'b0; result <= 32'h00000000; end end end endmodule